3	import { useState, useEffect, useMemo } from 'react'
4	import { useRouter } from 'next/navigation'
5	import { Users, SearchX } from 'lucide-react'
6	import { ArtistCard } from '@/components/artists/ArtistCard'
7	import { ArtistTable } from '@/components/artists/ArtistTable'
8	import { ArtistListHeader, type ArtistViewMode } from '@/components/artists/ArtistListHeader'
9	import { ArtistFilterBar, type ArtistFilters } from '@/components/artists/ArtistFilterBar'
10	import { InviteModal } from '@/components/settings/team/InviteModal'
11	import { DataState } from '@/components/shared/DataState'
12	import { EmptyState } from '@/components/shared/EmptyState'
13	import { PageError } from '@/components/shared/PageError'
14	import type { ArtistCardData } from '@/components/artists/ArtistCard'
15	
16	const STORAGE_KEY = 'inkos:artists:view'
17	
18	/**
19	 * S13 — Extracted from former /artists/page.tsx (which was a pure client component).
20	 * Now used as the "Roster" tab content inside the /artists tab host server page.
21	 */
22	export function ArtistsRosterClient() {
23	  const router = useRouter()
24	  const [viewMode, setViewMode] = useState<ArtistViewMode>('grid')
25	  const [artists, setArtists] = useState<ArtistCardData[]>([])
26	  const [loading, setLoading] = useState(true)
27	  const [fetchError, setFetchError] = useState<Error | null>(null)
28	  const [showInviteModal, setShowInviteModal] = useState(false)
29	  const [filters, setFilters] = useState<ArtistFilters>({
30	    status: 'all',
31	    specialty: 'all',
32	    role: 'all',
33	  })
34	
35	  useEffect(() => {
36	    const stored = localStorage.getItem(STORAGE_KEY)
37	    if (stored === 'grid' || stored === 'table') setViewMode(stored)
38	  }, [])
39	
40	  const handleViewModeChange = (mode: ArtistViewMode) => {
41	    setViewMode(mode)
42	    localStorage.setItem(STORAGE_KEY, mode)
43	  }
44	
45	  const fetchArtists = async () => {
46	    setLoading(true)
47	    setFetchError(null)
48	    try {
49	      const res = await fetch('/api/artists')
50	      if (!res.ok) throw new Error('Failed to fetch artists')
51	      const json = await res.json() as { data: ArtistCardData[] }
52	      setArtists(json.data ?? [])
53	    } catch (err) {
54	      setFetchError(err instanceof Error ? err : new Error('Could not load artists'))
55	    } finally {
56	      setLoading(false)
57	    }
58	  }
59	
60	  useEffect(() => {
61	    void fetchArtists()
62	  }, [])
63	
64	  const allSpecialties = useMemo(() => {
65	    const set = new Set<string>()
66	    artists.forEach((a) => a.specialties.forEach((s) => set.add(s)))
67	    return [...set].sort()
68	  }, [artists])
69	
70	  const filtered = useMemo(() => {
71	    return artists.filter((a) => {
72	      if (filters.status !== 'all' && a.status !== filters.status) return false
73	      if (filters.specialty !== 'all' && filters.specialty != null && !a.specialties.includes(filters.specialty)) return false
74	      if (filters.role !== 'all' && a.role !== filters.role) return false
75	      return true
76	    })
77	  }, [artists, filters])
78	
79	  const hasActiveFilters =
80	    filters.status !== 'all' || filters.specialty !== 'all' || filters.role !== 'all'
81	
82	  const clearFilters = () =>
83	    setFilters({ status: 'all', specialty: 'all', role: 'all' })
84	
85	  const gridSkeleton = (
86	    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
87	      {Array.from({ length: 8 }).map((_, i) => (
88	        <div key={i} className="h-[168px] rounded-xl bg-muted animate-pulse" />
89	      ))}
90	    </div>
91	  )
92	
93	  return (
94	    <div className="flex flex-col min-h-0">
95	      <ArtistListHeader
96	        viewMode={viewMode}
97	        onViewModeChange={handleViewModeChange}
98	        onAddArtist={() => router.push('/artists/new')}
99	        onInviteArtist={() => setShowInviteModal(true)}
100	      />
101	
102	      <ArtistFilterBar
103	        filters={filters}
104	        onFiltersChange={setFilters}
105	        totalCount={artists.length}
106	        filteredCount={filtered.length}
107	        specialties={allSpecialties}
108	      />
109	
110	      <div className="flex-1 p-6">
111	        <DataState
112	          data={artists}
113	          isLoading={loading}
114	          isError={!!fetchError}
115	          error={fetchError}
116	          loadingSlot={gridSkeleton}
117	          emptySlot={
118	            <EmptyState
119	              icon={Users}
120	              title="No artists yet"
121	              description="Add your first artist or invite them to join your studio."
122	              cta={{ label: '+ Add Artist', onClick: () => router.push('/artists/new') }}
123	              ctaSecondary={{ label: 'Invite Artist', onClick: () => setShowInviteModal(true) }}
124	              variant="first-time"
125	            />
126	          }
127	          errorSlot={
128	            <PageError
129	              error={fetchError ?? new Error('Failed to load artists')}
130	              reset={() => void fetchArtists()}
131	              variant="inline"
132	            />
133	          }
134	        >
135	          {(_data) => (
136	            <>
137	              {hasActiveFilters && filtered.length === 0 ? (
138	                <EmptyState
139	                  icon={SearchX}
140	                  title="No artists match"
141	                  description="Try a different status, specialty, or role filter."
142	                  cta={{ label: 'Clear filters', onClick: clearFilters }}
143	                  variant="no-results"
144	                />
145	              ) : viewMode === 'grid' ? (
146	                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
147	                  {filtered.map((artist) => (
148	                    <ArtistCard key={artist.id} artist={artist} />
149	                  ))}
150	                </div>
151	              ) : (
152	                <ArtistTable
153	                  artists={filtered}
154	                  canDeactivate={true}
155	                  onDeactivate={(id) => { void id }}
156	                />
157	              )}
158	            </>
159	          )}
160	        </DataState>
161	      </div>
162	
163	      {showInviteModal && (
164	        <InviteModal
165	          open={showInviteModal}
166	          onOpenChange={setShowInviteModal}
167	          defaultRole="artist"
168	          onSuccess={() => {
169	            setShowInviteModal(false)
170	            void fetchArtists()
171	          }}
172	        />
173	      )}
174	    </div>
175	  )
176	}
