'use client'

import { usePathname } from 'next/navigation'
import Link from 'next/link'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { Badge } from '@/components/ui/badge'
import type { NavGroup } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { cn } from '@/lib/utils'

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
  isFirst?: boolean
}

export function SidebarNavGroup({ group, plan, isFirst }: SidebarNavGroupProps) {
  const pathname = usePathname()

  return (
    <SidebarGroup className={cn('px-0', isFirst ? 'pt-0' : 'pt-4')}>
      <SidebarGroupLabel className="mb-1 px-2.5 text-[10px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/50 group-data-[collapsible=icon]:hidden">
        {group.label}
      </SidebarGroupLabel>
      <SidebarMenu className="gap-0.5">
        {group.items.map((item) => {
          const isActive =
            pathname === item.href || pathname.startsWith(item.href + '/')

          const isGated =
            !!item.requiredPlan &&
            !!item.featureKey &&
            !hasFeature(plan, item.featureKey)

          return (
            <SidebarMenuItem key={item.href}>
              <SidebarMenuButton
                render={<Link href={item.href} />}
                isActive={isActive}
                className={cn(
                  'group/item relative h-8 gap-2.5 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
                  'text-sidebar-foreground/65 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
                  'data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground data-[active=true]:font-semibold',
                  'data-[active=true]:before:absolute data-[active=true]:before:left-0 data-[active=true]:before:top-1/2 data-[active=true]:before:h-4 data-[active=true]:before:w-0.5 data-[active=true]:before:-translate-y-1/2 data-[active=true]:before:rounded-r-full data-[active=true]:before:bg-primary',
                )}
                tooltip={item.label}
              >
                <item.icon
                  className={cn(
                    '!h-[16px] !w-[16px] shrink-0 transition-opacity',
                    isActive ? 'opacity-100 text-primary' : 'opacity-55 group-hover/item:opacity-80',
                  )}
                  aria-hidden="true"
                />
                <span className="truncate group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>
                {isGated && (
                  <Badge
                    variant="outline"
                    className="ml-auto h-[17px] border-primary/25 bg-primary/10 px-1.5 py-0 text-[9px] font-semibold tracking-wide text-primary group-data-[collapsible=icon]:hidden"
                  >
                    Pro
                  </Badge>
                )}
                {item.badge && !isGated && (
                  <Badge
                    variant="outline"
                    className="ml-auto h-[17px] border-emerald-500/25 bg-success/10 px-1.5 py-0 text-[9px] font-semibold tracking-wide text-success group-data-[collapsible=icon]:hidden"
                  >
                    {item.badge === 'new' ? 'New' : 'Beta'}
                  </Badge>
                )}
              </SidebarMenuButton>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

